{
  "title": "竹林试炼",
  "scene": "你漫步在竹林小径上，清风拂过，带来阵阵竹叶的清香。前方不远处，一位白发武者正闭目养神，手中握着一根长笛。他似乎察觉到你的到来，缓缓睁开眼睛，微笑着对你说：‘来者何人？是否愿意接受老夫的试炼？’。竹林深处，隐隐传来拳风与剑鸣之声，像是有高手在练武。你心中暗自思量，这试炼会是一场怎样的考验。",
  "goal": "通过武者的试炼",
  "clue": "白发武者手中的长笛暗示他不仅是高人，还有音乐方面的特长。",
  "choices": [
    {
      "id": "A",
      "text": "接受试炼，请求指导",
      "outcome": "武者点了点头，脸上露出赞许之色。‘好，年轻人有朝气！老夫就教你一招。’他轻挥长笛，动作如行云流水，你跟在他身后，学到了一套精妙的笛法。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "询问试炼的内容",
      "outcome": "武者的笑容更加温和，‘试炼就是考验你的心境与悟性。老夫喜欢你的谨慎，来，跟我一起练练心法。’你跟着他，学会了如何在战斗中保持冷静。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "婉言谢绝，继续前行",
      "outcome": "武者的眼神中闪过一丝失望，但并未强求，只是轻轻摇了摇头。‘算了，是你的选择。竹林深处有更多高手，你去吧。’你感到有些可惜，但还是继续前行。",
      "result": "fail",
      "next": "retry"
    }
  ]
}
